package br.com.onda;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.*;import android.view.*;import android.widget.*;import android.view.accessibility.AccessibilityNodeInfo;
import androidx.media3.common.*;import androidx.media3.session.*;import com.google.common.util.concurrent.ListenableFuture;
import java.io.*;import java.nio.*;import java.util.*;import java.util.concurrent.*;
import org.junit.Test;import static org.junit.Assert.*;import static androidx.test.platform.app.InstrumentationRegistry.getInstrumentation;
@androidx.media3.common.util.UnstableApi
public class CleanInterfaceTest {
 private final Instrumentation ins=getInstrumentation();private final Context context=ins.getTargetContext();
 private View find(View v,String description){if(description.contentEquals(v.getContentDescription()==null?"":v.getContentDescription()))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View f=find(((ViewGroup)v).getChildAt(i),description);if(f!=null)return f;}return null;}
 private View text(View v,String label){if(v instanceof TextView&&label.contentEquals(((TextView)v).getText()))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View f=text(((ViewGroup)v).getChildAt(i),label);if(f!=null)return f;}return null;}
 private Object field(Object owner,String name)throws Exception{java.lang.reflect.Field f=owner.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(owner);}
 private void capture(String name)throws Exception{android.graphics.Bitmap b=ins.getUiAutomation().takeScreenshot();if(b!=null)try(OutputStream out=new FileOutputStream(new File(context.getFilesDir(),name+".png"))){b.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}finally{b.recycle();}}
 @Test public void secondaryDownloadActionsStayReachableWithoutFillingTheInitialScreen()throws Exception{
  DownloadsActivity a=(DownloadsActivity)ins.startActivitySync(new Intent(context,DownloadsActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));try{ins.waitForIdleSync();ins.runOnMainSync(()->{View root=a.findViewById(android.R.id.content);assertTrue(find(root,"Link do vídeo").isShown());View quality=text(root,"Qualidade MP3");assertNotNull(quality);assertFalse(quality.isShown());assertNotNull(find(root,"Como funcionam os downloads"));View reveal=find(root,"Mostrar Opções de download");assertNotNull(reveal);assertTrue(reveal.performClick());assertTrue(quality.isShown());for(String label:new String[]{"Pasta do Onda e histórico","Abrir último arquivo","Compartilhar arquivo baixado","Relatório de downloads","Licença e código-fonte"})assertNotNull(label,text(root,label));assertTrue(find(root,"Ocultar Opções de download").performClick());assertFalse(quality.isShown());});capture("clean-downloads");}finally{ins.runOnMainSync(a::finish);}
 }
 @Test public void liveSettingsCanBeChangedAndCollapsedWithoutStartingRecognition()throws Exception{
  LiveLyricsActivity a=(LiveLyricsActivity)ins.startActivitySync(new Intent(context,LiveLyricsActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));try{ins.waitForIdleSync();ins.runOnMainSync(()->{try{View root=a.findViewById(android.R.id.content);assertNull(LiveAudioTap.receiver);assertFalse(find(root,"Idioma cantado no reconhecimento ao vivo").isShown());assertTrue(find(root,"Mostrar Idiomas e modelo").performClick());Spinner from=(Spinner)field(a,"source"),to=(Spinner)field(a,"target");from.setSelection(1);int destination=to.getSelectedItemPosition();assertTrue(from.isShown());assertTrue(find(root,"Ocultar Idiomas e modelo").performClick());assertFalse(from.isShown());assertEquals(1,from.getSelectedItemPosition());assertEquals(destination,to.getSelectedItemPosition());assertNull(field(a,"recognizer"));assertNull(LiveAudioTap.receiver);}catch(Exception e){throw new RuntimeException(e);}});ins.waitForIdleSync();capture("clean-live-lyrics");ins.runOnMainSync(()->assertTrue(find(a.findViewById(android.R.id.content),"Como funciona").performClick()));ins.waitForIdleSync();AccessibilityNodeInfo node=null;long windowBy=SystemClock.elapsedRealtime()+4000;boolean explained=false;while(SystemClock.elapsedRealtime()<windowBy){node=ins.getUiAutomation().getRootInActiveWindow();if(node!=null&&!node.findAccessibilityNodeInfosByText("microfone").isEmpty()){explained=true;break;}Thread.sleep(100);}assertTrue("Full explanation must remain accessible",explained);try(InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(ins.getUiAutomation().executeShellCommand("input keyevent 4"))){while(in.read()!=-1){}}assertNull(LiveAudioTap.receiver);
  }finally{ins.runOnMainSync(a::finish);}
 }
 private File audio()throws Exception{File f=File.createTempFile("clean-interface-",".wav",context.getCacheDir());int seconds=40,bytes=16000*seconds*2;ByteBuffer header=ByteBuffer.allocate(44).order(ByteOrder.LITTLE_ENDIAN);header.putInt(0x46464952).putInt(bytes+36).putInt(0x45564157).putInt(0x20746d66).putInt(16).putShort((short)1).putShort((short)1).putInt(16000).putInt(32000).putShort((short)2).putShort((short)16).putInt(0x61746164).putInt(bytes);ByteBuffer pcm=ByteBuffer.allocate(32000).order(ByteOrder.LITTLE_ENDIAN);for(int n=0;n<16000;n++)pcm.putShort((short)(3000*Math.sin(2*Math.PI*440*n/16000)));try(OutputStream out=new FileOutputStream(f)){out.write(header.array());for(int s=0;s<seconds;s++)out.write(pcm.array());}return f;}
 @Test public void visualModeAndThemesChangeWithoutRestartingOrPausingMusic()throws Exception{
  SharedPreferences prefs=context.getSharedPreferences("appearance",0);boolean had=prefs.contains("clean_interface"),old=prefs.getBoolean("clean_interface",true);String theme=prefs.getString("theme",null);File song=audio();AppearanceActivity a=(AppearanceActivity)ins.startActivitySync(new Intent(context,AppearanceActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));ListenableFuture<MediaController>[] connection=new ListenableFuture[1];ins.runOnMainSync(()->connection[0]=new MediaController.Builder(context,new SessionToken(context,new ComponentName(context,PlaybackService.class))).buildAsync());MediaController player=connection[0].get(15,TimeUnit.SECONDS);
  try{ins.runOnMainSync(()->{player.setRepeatMode(Player.REPEAT_MODE_OFF);player.setMediaItem(new MediaItem.Builder().setMediaId("clean-interface-playing").setUri(Uri.fromFile(song)).build());player.prepare();player.play();});long until=SystemClock.elapsedRealtime()+10000;boolean[] playing={false};while(SystemClock.elapsedRealtime()<until){ins.runOnMainSync(()->playing[0]=player.isPlaying());if(playing[0])break;Thread.sleep(100);}assertTrue(playing[0]);long[] before={0};ins.runOnMainSync(()->{before[0]=player.getCurrentPosition();AppearanceStyles.choose(a,AppearancePalette.find("festival"));View root=a.findViewById(android.R.id.content);assertTrue(find(root,"Mostrar Opções de estilo").performClick());Switch clean=(Switch)find(root,"Visual limpo do Onda");assertNotNull(clean);clean.setChecked(false);assertFalse(Ui.CLEAN);clean.setChecked(true);assertTrue(Ui.CLEAN);assertTrue(player.isPlaying());assertEquals("clean-interface-playing",player.getCurrentMediaItem().mediaId);assertFalse(a.isFinishing());});Thread.sleep(750);ins.runOnMainSync(()->{assertTrue(player.isPlaying());assertTrue(player.getCurrentPosition()>before[0]);assertTrue(prefs.getBoolean("clean_interface",false));});ins.runOnMainSync(a::finish);ins.waitForIdleSync();AppearanceActivity again=(AppearanceActivity)ins.startActivitySync(new Intent(context,AppearanceActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));try{ins.runOnMainSync(()->{View root=again.findViewById(android.R.id.content);find(root,"Mostrar Opções de estilo").performClick();assertTrue(((Switch)find(root,"Visual limpo do Onda")).isChecked());assertTrue(player.isPlaying());});}finally{ins.runOnMainSync(again::finish);}
  }finally{ins.runOnMainSync(()->{player.pause();player.clearMediaItems();MediaController.releaseFuture(connection[0]);a.finish();SharedPreferences.Editor e=prefs.edit();if(had)e.putBoolean("clean_interface",old);else e.remove("clean_interface");if(theme==null)e.remove("theme");else e.putString("theme",theme);e.commit();((OndaApplication)context.getApplicationContext()).refreshAll();});song.delete();}
 }
}
